package co.edu.fet.agendad.gateway;
import org.springframework.beans.factory.annotation.Value;import org.springframework.graphql.data.method.annotation.Argument;import org.springframework.graphql.data.method.annotation.QueryMapping;import org.springframework.stereotype.Controller;import org.springframework.web.client.RestClient;import java.time.*;import java.util.*;
@Controller public class PanelController {private final RestClient http;private final String agenda,analitica;public PanelController(RestClient h,@Value("${agendad.agenda-url}")String a,@Value("${agendad.analitica-url}")String n){http=h;agenda=a;analitica=n;}
 @QueryMapping public Map<String,Object> panelRecepcion(@Argument String negocioId,@Argument String fecha){LocalDate f=fecha==null?LocalDate.now(ZoneId.of("America/Bogota")):LocalDate.parse(fecha);UUID negocio=UUID.fromString(negocioId);Map panel=http.get().uri(agenda+"/v1/interno/panel?negocioId={n}&fecha={f}",negocio,f).retrieve().body(Map.class);Map m=http.get().uri(analitica+"/v1/metricas?desde={d}&hasta={h}",f.withDayOfMonth(1),f).header("X-Negocio-Id",negocio.toString()).retrieve().body(Map.class);Map negocioMap=new LinkedHashMap<>((Map)panel.get("negocio"));negocioMap.put("servicios",panel.get("servicios"));return Map.of("fecha",f.toString(),"negocio",negocioMap,"citasDelDia",panel.get("citas"),"metricasDelMes",m);}}
